import { cp, mkdir, rm, writeFile } from "node:fs/promises";
const destination = new URL("../server/internal/assets/dist/", import.meta.url);
await rm(destination, { recursive: true, force: true });
await mkdir(destination, { recursive: true });
await cp(new URL("../web/dist/", import.meta.url), destination, {
  recursive: true,
});
await writeFile(
  new URL("placeholder.txt", destination),
  "Frontend assets are generated by pnpm build:web.\n",
);
console.log("Frontend copied into the Go embed directory.");
